1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The single duplicate check of the create-owner pipeline: rejects the request with a 409 (via
11	 * {@code DuplicateIdentityExceptionHandler}) when the new owner's whole {@link IdentityKey} equals an
12	 * existing owner's. This consolidates the former separate telephone, email and household checks — all
13	 * three are now expressed through the one key.
14	 *
15	 * <p>Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail}, so the candidate's
16	 * telephone and email are already in their normalized form. The candidate's household id comes from
17	 * {@link HouseholdKey#candidateHouseholdId} — the same single definition {@link AssignHousehold} uses
18	 * to assign it — so the key and the assigned id cannot drift apart. Because the telephone is part of
19	 * the key, two members of the same household with different telephones have different keys and are
20	 * both allowed.
21	 *
22	 * <p>The new owner is not persisted yet, so every match found is another owner.
23	 */
24	public class RequireUniqueIdentity {
25	
26	    public void service(@Val OwnerFieldsDto owner, OwnerRepository ownerRepository)
27	            throws DuplicateIdentityException {
28	        String householdId = HouseholdKey.candidateHouseholdId(owner);
29	        String candidate = IdentityKey.of(owner.getTelephone(), owner.getEmail(), householdId);
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (candidate.equals(IdentityKey.ofOwner(existing))) {
32	                throw new DuplicateIdentityException(candidate);
33	            }
34	        }
35	    }
36	}
