1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * The single definition of an owner's {@code identityKey} — the one derived key that all duplicate
7	 * detection is expressed through. The key joins three normalized parts with {@code '|'}:
8	 *
9	 * <ol>
10	 * <li>the telephone in E.164 form (see {@link TelephoneNormalizer}),</li>
11	 * <li>the email lower-cased, or empty when absent (see {@link EmailNormalizer}), and</li>
12	 * <li>the {@code householdId}, or empty when the owner does not share a household.</li>
13	 * </ol>
14	 *
15	 * <p>A create is a duplicate — rejected with a 409 — only when its <em>whole</em> key equals an
16	 * existing owner's. Because the telephone is part of the key, two members of one household (the same
17	 * {@code householdId}) with different telephones have different keys and are both allowed.
18	 *
19	 * <p>Shared by {@link RequireUniqueIdentity} (which rejects a collision) and the owner mapper (which
20	 * returns the key), so both compute it the same way and cannot drift apart. Public because the mapper
21	 * lives in another package.
22	 */
23	public final class IdentityKey {
24	
25	    /** The identity key for the given (raw) telephone, email and household id. */
26	    public static String of(String telephone, String email, String householdId) {
27	        String tel = TelephoneNormalizer.toE164(telephone);
28	        if (tel == null) {
29	            tel = telephone == null ? "" : telephone;
30	        }
31	        String em = EmailNormalizer.isBlank(email) ? "" : EmailNormalizer.normalize(email);
32	        String hh = householdId == null ? "" : householdId;
33	        return tel + "|" + em + "|" + hh;
34	    }
35	
36	    /** The identity key of an existing (persisted) owner. */
37	    public static String ofOwner(Owner owner) {
38	        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
39	    }
40	
41	    private IdentityKey() {
42	    }
43	}
