1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Thrown by {@code RequireUniqueIdentity} when a create-owner request's whole derived
5	 * {@code identityKey} equals an existing owner's. Carries the offending key so
6	 * {@link DuplicateIdentityExceptionHandler} can report a 409.
7	 */
8	public class DuplicateIdentityException extends Exception {
9	
10	    private final String identityKey;
11	
12	    public DuplicateIdentityException(String identityKey) {
13	        super("Owner identity is already used by another owner: '" + identityKey + "'");
14	        this.identityKey = identityKey;
15	    }
16	
17	    public String getIdentityKey() {
18	        return this.identityKey;
19	    }
20	}
