1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	import java.util.List;
4	import java.util.Map;
5	
6	import net.officefloor.plugin.section.clazz.Parameter;
7	import net.officefloor.web.ObjectResponse;
8	import org.springframework.http.HttpStatus;
9	import org.springframework.http.ResponseEntity;
10	
11	/**
12	 * Responds 409 when a create-owner request's whole {@code identityKey} is already used by another
13	 * owner, mirroring the other create-conflict handlers' {@code errors} array shape.
14	 */
15	public class DuplicateIdentityExceptionHandler {
16	
17	    public void handle(@Parameter DuplicateIdentityException ex,
18	            ObjectResponse<ResponseEntity<Map<String, Object>>> response) {
19	        response.send(ResponseEntity.status(HttpStatus.CONFLICT)
20	                .body(Map.of("errors", List.of("identityKey"))));
21	    }
22	}
