1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * When a create-owner request sets {@code sharesHousehold} true, the new owner is allowed to share a
10	 * household with the existing owner(s) at the same address and last name (see {@link HouseholdKey}).
11	 * This step assigns the new owner — and every matching existing owner that does not already carry one
12	 * — the same stable {@code householdId}, so the whole household shares one identifier.
13	 *
14	 * <p>Requests that do not set {@code sharesHousehold} leave the owner without a household id.
15	 */
16	public class AssignHousehold {
17	
18	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
19	        String householdId = HouseholdKey.candidateHouseholdId(request);
20	        if (householdId == null) {
21	            return;
22	        }
23	        HouseholdKey household = HouseholdKey.of(owner.getLastName(), owner.getAddress());
24	        owner.setHouseholdId(householdId);
25	
26	        // Backfill the existing household members so the whole household shares the identifier.
27	        // These are pre-existing side entities, not the request's new owner, so they are saved
28	        // directly here rather than through the pipeline's save: step (which persists only the
29	        // new owner mutated above).
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (household.matches(existing) && !householdId.equals(existing.getHouseholdId())) {
32	                existing.setHouseholdId(householdId);
33	                ownerRepository.save(existing);
34	            }
35	        }
36	    }
37	}
