1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * The single definition of the E.164 form of a telephone number. Shared by
7	 * {@link NormalizeOwnerTelephone} (which stores the E.164 value) and {@link IdentityKey}
8	 * (which folds it into the duplicate-detection key), so both apply the same rule and cannot drift apart.
9	 *
10	 * <p>The rule: strip spaces, dashes and brackets. When a leading {@code '+'} is present, keep it and
11	 * the country code that follows; otherwise assume country code {@code '+61'} and drop a single leading
12	 * {@code '0'} from the national digits. The result must carry 8 to 15 digits after the {@code '+'};
13	 * anything else cannot form valid E.164 and yields {@code null}.
14	 *
15	 * <p>The national-number length is also checked against the country code: {@code '+61'} (Australia)
16	 * requires exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10. A number for one of
17	 * those countries whose national part is the wrong length cannot form valid E.164 and yields
18	 * {@code null} (rejected with a 400). Other country codes keep only the generic 8-to-15 length rule.
19	 *
20	 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
21	 * expose exactly one public method.
22	 */
23	final class TelephoneNormalizer {
24	
25	    /**
26	     * Country code (the digits after the {@code '+'}) to its required national-number length. Country
27	     * codes absent here keep only the generic 8-to-15 rule. Adding a country is a new entry, not a new
28	     * branch.
29	     */
30	    private static final Map<String, Integer> NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
31	
32	    /**
33	     * Returns the E.164 form of the given telephone, or {@code null} when it cannot form a valid one.
34	     */
35	    static String toE164(String telephone) {
36	        if (telephone == null) {
37	            return null;
38	        }
39	        // Strip spaces, dashes and brackets.
40	        String cleaned = telephone.replaceAll("[\\s()-]", "");
41	        String digits;
42	        if (cleaned.startsWith("+")) {
43	            // Explicit country code: keep the digits that follow the '+'.
44	            digits = cleaned.substring(1);
45	        }
46	        else {
47	            // No country code: assume +61 and drop a single leading '0' from the national digits.
48	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
49	            digits = "61" + national;
50	        }
51	        // Everything after the '+' must be 8 to 15 digits.
52	        if (!digits.matches("\\d{8,15}")) {
53	            return null;
54	        }
55	        // Per-country national-number length: +61 (Australia) needs 9 national digits, +1 (NANP)
56	        // needs 10. Country codes not listed keep only the generic 8-to-15 rule above.
57	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH.entrySet()) {
58	            String countryCode = entry.getKey();
59	            if (digits.startsWith(countryCode)
60	                    && digits.length() - countryCode.length() != entry.getValue()) {
61	                return null;
62	            }
63	        }
64	        return "+" + digits;
65	    }
66	
67	    private TelephoneNormalizer() {
68	    }
69	}
