1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.regex.Pattern;
4	
5	/**
6	 * The single definition of a valid, normalized owner email. An email is optional: a {@code null} or
7	 * blank value is left untouched (the owner simply has no email). When a non-blank value is present it
8	 * must be a syntactically valid address; the normalized form is the same address lower-cased.
9	 *
10	 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
11	 * expose exactly one public method.
12	 */
13	final class EmailNormalizer {
14	
15	    private static final Pattern EMAIL = Pattern.compile(
16	            "^[A-Za-z0-9._%+\\-]+@[A-Za-z0-9.\\-]+\\.[A-Za-z]{2,}$");
17	
18	    /** A blank (null/empty/whitespace) value counts as "no email supplied". */
19	    static boolean isBlank(String email) {
20	        return email == null || email.isBlank();
21	    }
22	
23	    static boolean isValid(String email) {
24	        return EMAIL.matcher(email.trim()).matches();
25	    }
26	
27	    /** Lower-case the (already validated, non-blank) address. */
28	    static String normalize(String email) {
29	        return email.trim().toLowerCase();
30	    }
31	
32	    private EmailNormalizer() {
33	    }
34	}
