1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	
10	/**
11	 * Runs after {@link ValidateOwner} in the create-owner pipeline and enforces the one rule the DTO's
12	 * declarative constraints cannot express: no required field may be <em>blank</em>. {@code address} and
13	 * {@code city} carry only {@code @Size(min = 1)} (no pattern), so a whitespace-only value passes schema
14	 * validation; this step rejects it with a 400 listing every offending field.
15	 *
16	 * <p>Layered on top of {@code @Valid} rather than replacing it: null/empty/pattern violations are still
17	 * caught upstream by {@link ValidateOwner} (consistent with {@code PUT /owners/{ownerId}}), and both
18	 * paths surface the offending field names in the response {@code errors} array.
19	 */
20	public class RequireOwnerFields {
21	
22	    public void service(@Val OwnerFieldsDto owner) throws MissingOwnerFieldsException {
23	        List<String> missing = new ArrayList<>();
24	        if (isBlank(owner.getFirstName())) {
25	            missing.add("firstName");
26	        }
27	        if (isBlank(owner.getLastName())) {
28	            missing.add("lastName");
29	        }
30	        if (isBlank(owner.getAddress())) {
31	            missing.add("address");
32	        }
33	        if (isBlank(owner.getCity())) {
34	            missing.add("city");
35	        }
36	        if (isBlank(owner.getTelephone())) {
37	            missing.add("telephone");
38	        }
39	        if (!missing.isEmpty()) {
40	            throw new MissingOwnerFieldsException(missing);
41	        }
42	    }
43	
44	    private static boolean isBlank(String value) {
