1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * The single definition of the normalized form of an owner address. Shared by
7	 * {@link NormalizeOwnerAddress} (which stores the normalized value) and {@link HouseholdKey}
8	 * (which compares against it for duplicate detection and the shared household id), so every place
9	 * that stores, returns or compares an address applies the same rule and they cannot drift apart.
10	 *
11	 * <p>The rule: trim, collapse runs of whitespace to a single space, upper-case, and expand the
12	 * common street-type abbreviations word-by-word ({@code ST -> STREET}, {@code RD -> ROAD},
13	 * {@code AVE -> AVENUE}). A {@code null} or whitespace-only value normalizes to the empty string.
14	 *
15	 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
16	 * expose exactly one public method.
17	 */
18	final class AddressNormalizer {
19	
20	    private static final Map<String, String> ABBREVIATIONS = Map.of(
21	            "ST", "STREET",
22	            "RD", "ROAD",
23	            "AVE", "AVENUE");
24	
25	    /** Returns the normalized form of the given address; {@code null}/blank yields {@code ""}. */
26	    static String normalize(String address) {
27	        if (address == null) {
28	            return "";
29	        }
30	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
31	        if (collapsed.isEmpty()) {
32	            return "";
33	        }
34	        String[] words = collapsed.split(" ");
35	        for (int i = 0; i < words.length; i++) {
36	            String expanded = ABBREVIATIONS.get(words[i]);
37	            if (expanded != null) {
38	                words[i] = expanded;
39	            }
40	        }
41	        return String.join(" ", words);
42	    }
43	
44	    private AddressNormalizer() {
45	    }
46	}
