2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's canonical region ("locality") from their city using a fixed
7	 * city-to-region table. The mapping is intentionally pinned so both the Spring and
8	 * OfficeFloor arms produce identical values; anything not in the table is "UNKNOWN".
9	 */
10	public final class Localities {
11	
12	    /** City -> canonical region. */
13	    private static final Map<String, String> CITY_REGION = Map.of(
14	            "Sydney", "NSW",
15	            "Melbourne", "VIC",
16	            "Brisbane", "QLD");
17	
18	    /** Locality returned for any city not in {@link #CITY_REGION}. */
19	    public static final String UNKNOWN = "UNKNOWN";
20	
21	    /** Region -> inclusive 4-digit postcode range {low, high}. Regions absent here (UNKNOWN) accept
22	     *  any 4-digit postcode. Pinned to match the acceptance spec's fixed table. */
23	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
24	            "NSW", new int[] {2000, 2099},
25	            "VIC", new int[] {3000, 3099},
26	            "QLD", new int[] {4000, 4099});
27	
28	    private Localities() {
29	    }
30	
31	    /** The canonical region for {@code city}, or "UNKNOWN" when the city is not in the table. */
32	    public static String of(String city) {
33	        return CITY_REGION.getOrDefault(city, UNKNOWN);
34	    }
35	
36	    /**
37	     * The canonical region derived from the {@code postcode} alone — the region whose range contains
38	     * it, or "UNKNOWN" when the postcode is absent, blank, non-numeric or in no known range. This is
39	     * the region embedded in an owner's {@code customerCode}.
40	     */
41	    public static String ofPostcode(String postcode) {
42	        String byPostcode = regionForPostcode(postcode);
43	        return byPostcode != null ? byPostcode : UNKNOWN;
44	    }
45	
46	    /** The region whose inclusive range contains {@code postcode}, or {@code null} when the postcode is
47	     *  absent, blank, non-numeric or in no known range. */
48	    private static String regionForPostcode(String postcode) {
49	        if (postcode == null || postcode.isBlank()) {
50	            return null;
51	        }
52	        int value;
53	        try {
54	            value = Integer.parseInt(postcode.trim());
55	        }
56	        catch (NumberFormatException ex) {
57	            return null;
58	        }
59	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
60	            int[] range = entry.getValue();
61	            if (value >= range[0] && value <= range[1]) {
62	                return entry.getKey();
63	            }
64	        }
65	        return null;
66	    }
67	
68	    /** The inclusive {low, high} postcode range for {@code city}'s region, or {@code null} when the
69	     *  city has no known region (any 4-digit postcode is then accepted). */
70	    public static int[] postcodeRange(String city) {
71	        return REGION_POSTCODES.get(of(city));
72	    }
73	}
