2	
3	import org.springframework.samples.petclinic.rest.function.common.Localities;
4	
5	/**
6	 * The single definition of an owner's {@code customerCode} format — {@code <REGION>-<HASH8>}, a
7	 * region code and an 8-character hash joined by {@code '-'}. Co-locates construction ({@link #format})
8	 * and read-back ({@link #regionOf}) so both agree on the separator and layout and cannot drift apart,
9	 * the same idiom {@link IdentityKey} uses for the identity key.
10	 *
11	 * <p>Shared by {@link AssignOwnerCustomerCode} (which builds the code) and the owner mapper (which
12	 * reads the region back out as the owner's locality). Public because the mapper lives in another
13	 * package.
14	 */
15	public final class CustomerCode {
16	
17	    /** The character separating the region from the hash. */
18	    private static final char SEPARATOR = '-';
19	
20	    /** The customer code for the given region and hash segment. */
21	    public static String format(String region, String hash8) {
22	        return region + SEPARATOR + hash8;
23	    }
24	
25	    /**
26	     * The region segment of a {@code <REGION>-<HASH8>} customer code — everything before the first
27	     * {@code '-'} — or {@link Localities#UNKNOWN} when the code is absent or blank.
28	     */
29	    public static String regionOf(String customerCode) {
30	        if (customerCode == null || customerCode.isBlank()) {
31	            return Localities.UNKNOWN;
32	        }
33	        int dash = customerCode.indexOf(SEPARATOR);
34	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
35	    }
36	
37	    private CustomerCode() {
38	    }
39	}
